import PDFDocument from 'pdfkit';
import type { FinancialModelRecord } from '../src/types/financial';
import { buildSensitivityMatrix } from '../src/lib/financialModel';

const LEGAL_DISCLAIMER =
  'This analysis was generated by AI and is provided for informational purposes only. It does not constitute financial advice, investment recommendations, or an offer to buy or sell securities. Users should independently verify all data and consult with qualified financial advisors before making investment decisions.';

const fmtCurrency = (n: number): string => {
  const abs = Math.abs(n);
  const str = abs.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  return n < 0 ? `(${str})` : str;
};

const fmtPct = (n: number | null): string => (n === null ? '—' : `${(n * 100).toFixed(1)}%`);

export function generateEquityResearchPdf(
  model: FinancialModelRecord,
  analystName: string
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'LETTER', margin: 48, bufferPages: true });
    const chunks: Buffer[] = [];
    doc.on('data', (c) => chunks.push(c));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const upside = model.dcfOutput.upsideDownsidePct;
    const rating = upside >= 0.12 ? 'BUY' : upside <= -0.1 ? 'SELL' : 'HOLD';
    const ratingColor = rating === 'BUY' ? '#15803D' : rating === 'SELL' ? '#B91C1C' : '#B45309';

    // PAGE 1: COVER & EXECUTIVE SUMMARY
    doc.rect(0, 0, 612, 92).fill('#1A1A2E');
    doc.fillColor('#FFFFFF').fontSize(10).font('Helvetica-Bold').text('FYNANCE BRO INSTITUTIONAL EQUITY RESEARCH', 48, 28);
    doc
      .fillColor('#9CA3AF')
      .fontSize(9)
      .font('Helvetica')
      .text(`Initiating Coverage Report  |  ${new Date().toISOString().slice(0, 10)}  |  Analyst: ${analystName}`, 48, 46);

    doc.fillColor('#111827').fontSize(22).font('Helvetica-Bold').text(model.companyInfo.companyName, 48, 114);
    doc
      .fillColor('#4B5563')
      .fontSize(11)
      .font('Helvetica')
      .text(`${model.companyInfo.exchange}: ${model.companyInfo.ticker}  ·  ${model.companyInfo.sector} — ${model.companyInfo.industry}`, 48, 142);

    // Rating & Valuation KPI Box
    doc.roundedRect(48, 170, 516, 74, 6).fillAndStroke('#F8FAFC', '#E2E8F0');
    doc.fillColor(ratingColor).fontSize(16).font('Helvetica-Bold').text(rating, 66, 186);
    doc.fillColor('#6B7280').fontSize(8).font('Helvetica').text('IMPLIED RATING', 66, 208);

    const kpis = [
      ['Target Price (DCF)', `$${model.dcfOutput.impliedSharePrice.toFixed(2)}`],
      ['Current Price', `$${model.companyInfo.stockPrice.toFixed(2)}`],
      ['Upside / Downside', `${upside >= 0 ? '+' : ''}${(upside * 100).toFixed(1)}%`],
      ['WACC / TGR', `${(model.dcfOutput.wacc * 100).toFixed(1)}% / ${(model.dcfOutput.terminalGrowthRate * 100).toFixed(1)}%`],
    ];
    kpis.forEach(([label, val], idx) => {
      const x = 165 + idx * 102;
      doc.fillColor('#111827').fontSize(13).font('Helvetica-Bold').text(val, x, 186);
      doc.fillColor('#6B7280').fontSize(8).font('Helvetica').text(label.toUpperCase(), x, 208);
    });

    // Executive Investment Summary
    doc.fillColor('#1A1A2E').fontSize(12).font('Helvetica-Bold').text('Investment Summary', 48, 264);
    const bullets = [
      `Base Case DCF implies an equity value of $${fmtCurrency(model.dcfOutput.equityValue)}M ($${model.dcfOutput.impliedSharePrice.toFixed(2)}/share), representing ${upside >= 0 ? '+' : ''}${(upside * 100).toFixed(1)}% vs current market pricing.`,
      `Model incorporates a ${model.forecastConfig.horizonYears}-year ${model.forecastConfig.riskProfile.toUpperCase()} risk forecast profile with ${fmtPct(model.dcfOutput.wacc)} WACC and ${fmtPct(model.dcfOutput.terminalGrowthRate)} perpetual growth.`,
      `Forward valuation multiples stand at ${model.dcfOutput.multiples.evToRevenue.toFixed(1)}x EV/Revenue, ${model.dcfOutput.multiples.evToEbitda.toFixed(1)}x EV/EBITDA, and ${model.dcfOutput.multiples.impliedPE.toFixed(1)}x Implied P/E.`,
    ];
    if (model.forecastConfig.aiRationale) {
      bullets.push(model.forecastConfig.aiRationale);
    }
    let y = 284;
    bullets.forEach((b) => {
      doc.fillColor('#111827').fontSize(9.5).font('Helvetica').text(`•  ${b}`, 52, y, { width: 510, lineGap: 3 });
      y = doc.y + 6;
    });

    // Company Overview
    doc.fillColor('#1A1A2E').fontSize(12).font('Helvetica-Bold').text('Company Overview', 48, y + 8);
    y = doc.y + 6;
    doc.fillColor('#374151').fontSize(9).font('Helvetica').text(model.companyInfo.description, 48, y, { width: 516, lineGap: 3 });

    // Key Metadata Strip
    y = doc.y + 12;
    doc
      .fillColor('#4B5563')
      .fontSize(8.5)
      .font('Helvetica')
      .text(
        `HQ: ${model.companyInfo.headquarters}   |   CEO: ${model.companyInfo.ceo}   |   FY End: ${model.companyInfo.fiscalYearEnd}   |   Employees: ${model.companyInfo.employees}`,
        48,
        y,
        { width: 516 }
      );

    // Footer Disclaimer Page 1
    doc
      .fillColor('#6B7280')
      .fontSize(7.5)
      .font('Helvetica-Oblique')
      .text(LEGAL_DISCLAIMER, 48, 705, { width: 516, align: 'justify' });

    // PAGE 2: FINANCIAL SUMMARY & PROJECTED STATEMENTS
    doc.addPage();
    doc.fillColor('#1A1A2E').fontSize(13).font('Helvetica-Bold').text('Financial Summary & Projections', 48, 48);
    doc
      .fillColor('#6B7280')
      .fontSize(8.5)
      .font('Helvetica')
      .text(`Units: ${model.companyInfo.currencyUnit} (except EPS)  ·  Shaded columns denote forecast periods`, 48, 66);

    const allIs = [...model.historical.incomeStatement, ...model.forecast.incomeStatement].slice(-7);
    const allCf = [...model.historical.cashFlow, ...model.forecast.cashFlow].slice(-7);

    const drawTable = (
      title: string,
      startY: number,
      headers: string[],
      rows: { label: string; values: string[]; bold?: boolean }[]
    ): number => {
      doc.fillColor('#1A1A2E').fontSize(10.5).font('Helvetica-Bold').text(title, 48, startY);
      let curY = startY + 18;
      const labelW = 166;
      const colW = Math.floor((516 - labelW) / headers.length);

      doc.rect(48, curY - 3, 516, 16).fill('#1A1A2E');
      doc.fillColor('#FFFFFF').fontSize(8).font('Helvetica-Bold').text('Line Item', 52, curY);
      headers.forEach((h, i) => {
        doc.text(h, 48 + labelW + i * colW, curY, { width: colW - 4, align: 'right' });
      });
      curY += 16;

      rows.forEach((row, rIdx) => {
        if (rIdx % 2 === 1) {
          doc.rect(48, curY - 2, 516, 14).fill('#F8FAFC');
        }
        doc
          .fillColor('#111827')
          .fontSize(8)
          .font(row.bold ? 'Helvetica-Bold' : 'Helvetica')
          .text(row.label, 52, curY, { width: labelW - 6 });
        row.values.forEach((v, i) => {
          doc.text(v, 48 + labelW + i * colW, curY, { width: colW - 4, align: 'right' });
        });
        curY += 14;
      });
      return curY + 14;
    };

    const isHeaders = allIs.map((x) => x.year);
    let nextY = drawTable('Income Statement Summary', 90, isHeaders, [
      { label: 'Revenue', values: allIs.map((x) => fmtCurrency(x.revenue)), bold: true },
      { label: 'Gross Profit', values: allIs.map((x) => fmtCurrency(x.grossProfit)) },
      { label: 'Operating Income (EBIT)', values: allIs.map((x) => fmtCurrency(x.ebit)), bold: true },
      { label: 'EBITDA', values: allIs.map((x) => fmtCurrency(x.ebitda)) },
      { label: 'Net Income', values: allIs.map((x) => fmtCurrency(x.netIncome)), bold: true },
      { label: 'Diluted EPS ($)', values: allIs.map((x) => `$${x.epsDiluted.toFixed(2)}`) },
      { label: 'Free Cash Flow (FCF)', values: allCf.map((x) => fmtCurrency(x.fcf)), bold: true },
    ]);

    const allBs = [...model.historical.balanceSheet, ...model.forecast.balanceSheet].slice(-7);
    nextY = drawTable('Balance Sheet Snapshot', nextY, allBs.map((x) => x.year), [
      { label: 'Cash & Equivalents', values: allBs.map((x) => fmtCurrency(x.cashAndEquivalents)) },
      { label: 'Total Current Assets', values: allBs.map((x) => fmtCurrency(x.totalCurrentAssets)) },
      { label: 'Total Assets', values: allBs.map((x) => fmtCurrency(x.totalAssets)), bold: true },
      { label: 'Total Debt (ST + LT)', values: allBs.map((x) => fmtCurrency(x.shortTermDebt + x.longTermDebt)) },
      { label: 'Total Liabilities', values: allBs.map((x) => fmtCurrency(x.totalLiabilities)) },
      { label: 'Shareholders Equity', values: allBs.map((x) => fmtCurrency(x.shareholdersEquity)), bold: true },
    ]);

    // Sensitivity Table on Page 2 bottom
    const sens = buildSensitivityMatrix(
      'wacc_tgr',
      model.companyInfo,
      model.historical,
      model.forecastConfig,
      model.forecast,
      model.dcfInputs,
      model.dcfOutput
    );
    drawTable(
      'DCF Sensitivity Matrix — Implied Share Price (WACC vs. Terminal Growth Rate)',
      nextY + 4,
      sens.xValues.map((x) => `${(x * 100).toFixed(1)}%`),
      sens.yValues.map((yVal, yIdx) => ({
        label: `WACC ${(yVal * 100).toFixed(1)}%`,
        values: sens.cells[yIdx].map((c) => `$${c.impliedPrice.toFixed(2)}`),
        bold: sens.cells[yIdx].some((c) => c.isBase),
      }))
    );

    doc
      .fillColor('#6B7280')
      .fontSize(7.5)
      .font('Helvetica-Oblique')
      .text(LEGAL_DISCLAIMER, 48, 705, { width: 516, align: 'justify' });

    doc.end();
  });
}
